/**
 * archViewWall.test.js -- K-1 SPINE (purity + the view wall + worker seam + the qualityLevel hook).
 *
 * The determinism perimeter is the arch/ subtree; the VIEW (the interactive WebGL viewer generated by
 * scripts/generate-k1.mjs) lives OUTSIDE it behind a one-way import wall. This pins:
 *   - PURITY: every arch/ file (INCLUDING the rulesets/ subdir, which k0GeometryTracery's non-
 *     recursive scan misses) calls ZERO transcendentals and uses no `**` -- cross-engine determinism.
 *   - THE VIEW WALL: no arch/ determinism file imports a view/component/script module or three.js;
 *     camera trig lives only in the (non-golden) generated viewer + the build script.
 *   - THE qualityLevel HOOK (K-5 governor amendment): the generated viewer exposes a single
 *     `qualityLevel` scalar the LOD selector + optional passes read, and NO arch/ golden file (mesh /
 *     emitter / plate / glb / interpreter) references it -- it can never touch geometry/plate/GLB.
 *   - THE WORKER SEAM: the emitter's outputs are transferable typed arrays (Float32Array/Uint32Array).
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { describe, it, expect } from 'vitest';
import { buildArchMesh } from '../../src/domain/townMap/arch/emitter.js';
import { cathedralRuleset } from '../../src/domain/townMap/arch/rulesets/cathedral.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '../..');
const ARCH_DIR = join(ROOT, 'src/domain/townMap/arch');

/** recursively collect every arch/*.js source path. */
function archFiles(dir = ARCH_DIR, out = []) {
  for (const f of readdirSync(dir)) {
    const p = join(dir, f);
    if (statSync(p).isDirectory()) archFiles(p, out);
    else if (f.endsWith('.js')) out.push(p);
  }
  return out;
}
/** strip block + line comments so doc prose does not trip the scans. */
function code(src) { return src.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/[^\n]*/g, '$1'); }

const FILES = archFiles();

describe('arch/ purity: the whole subtree (incl. rulesets/) is transcendental-free', () => {
  it('found the K-1 kernel files (guard-the-guard)', () => {
    const names = FILES.map((p) => p.replace(ARCH_DIR + '/', ''));
    for (const n of ['interpreter.js', 'ops.js', 'emitter.js', 'aoBake.js', 'plate.js', 'rulesets/cathedral.js', 'rulesets/buttressFragment.js']) {
      expect(names).toContain(n);
    }
  });
  it('no arch/ file calls a transcendental or uses **', () => {
    for (const p of FILES) {
      const c = code(readFileSync(p, 'utf8'));
      const rel = p.replace(ARCH_DIR + '/', '');
      expect(c, `${rel} calls Math.cos/sin/tan`).not.toMatch(/Math\s*\.\s*(cos|sin|tan|acos|asin|atan|atan2)\b/);
      expect(c, `${rel} calls Math.pow/exp/log/hypot`).not.toMatch(/Math\s*\.\s*(pow|exp|log|cbrt|hypot|sinh|cosh|tanh)\b/);
      expect(c, `${rel} uses the ** operator`).not.toMatch(/\*\*/);
    }
  });
});

describe('the view wall: arch/ imports only arch/ + kernel (no view, no three.js)', () => {
  it('no arch/ file imports a component/view/script module or three', () => {
    for (const p of FILES) {
      const c = code(readFileSync(p, 'utf8'));
      const rel = p.replace(ARCH_DIR + '/', '');
      const imports = [...c.matchAll(/\bfrom\s+['"]([^'"]+)['"]/g)].map((m) => m[1]);
      for (const spec of imports) {
        expect(spec, `${rel} imports view/UI module ${spec}`).not.toMatch(/components|\/ui\/|\.jsx|react/i);
        expect(spec, `${rel} imports three.js`).not.toMatch(/^three(\/|$)/);
        // only relative arch imports or the kernel prng are allowed
        const ok = spec.startsWith('.') || spec.includes('kernel/prng');
        expect(ok, `${rel} imports a non-arch, non-kernel module: ${spec}`).toBe(true);
      }
    }
  });
  it('package.json does not depend on three', () => {
    const pkg = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'));
    expect({ ...pkg.dependencies, ...pkg.devDependencies }.three).toBeUndefined();
  });
});

describe('the qualityLevel hook is view-only', () => {
  const viewerSrc = readFileSync(join(ROOT, 'scripts/generate-k1.mjs'), 'utf8');
  it('the generated viewer declares the qualityLevel scalar hook (default 1.0) read by LOD + passes', () => {
    expect(viewerSrc).toMatch(/let qualityLevel\s*=\s*1\.0/);
    expect(viewerSrc).toMatch(/lodTierFor/);   // LOD selector reads it
    expect(viewerSrc).toMatch(/inkEnabled/);   // the crease ink-line pass reads it
    expect(viewerSrc).toMatch(/resScale/);     // render-resolution scale reads it
  });
  it('NO golden arch/ file references qualityLevel (it can never touch geometry/plate/GLB)', () => {
    for (const p of FILES) {
      expect(readFileSync(p, 'utf8'), `${p} references qualityLevel -- the governor hook must stay in the view`).not.toMatch(/qualityLevel/);
    }
  });
});

describe('the worker seam: emitter outputs are transferable typed arrays', () => {
  const g = buildArchMesh(cathedralRuleset(), { seedId: 'k1', tier: 2 });
  it('positions/normals/ao are Float32Array; indices Uint32Array; triRole Uint8Array', () => {
    expect(g.positions).toBeInstanceOf(Float32Array);
    expect(g.normals).toBeInstanceOf(Float32Array);
    expect(g.ao).toBeInstanceOf(Float32Array);
    expect(g.indices).toBeInstanceOf(Uint32Array);
    expect(g.creaseEdges).toBeInstanceOf(Uint32Array);
    expect(g.triRole).toBeInstanceOf(Uint8Array);
  });
});
